VALUES ('club_cleveland-cleveland-mahjong-collective', 'Cleveland Mahjong Collective', 'cleveland-cleveland-mahjong-collective', 'Cleveland-area group running American Mahjong 101 lessons, guided play and open play at restaurants and cafes (Cleveland, Avon, Medina). Own site: "We celebrate different types of mahjong from American Mahjong (the style with the yearly cards and the ''Charleston'' swap) to the fast-paced, high-energy style of traditional Asian styles." Event pages: "Bring your 2026 NMJL card if you have one." Also runs some Chinese/Hong Kong style socials (not listed here).', (SELECT id FROM City WHERE name = 'Cleveland' AND state = 'OH'), 'Various venues in Cleveland, Avon and Medina, OH', 'https://www.clevelandmahjong.com/', NULL, NULL, NULL, NULL, 1, 1, 1, 1, 0, 0, NULL, 'Multiple sessions per week; tickets on Eventbrite (organizer page https://www.eventbrite.com/o/121189840863)', 'https://www.clevelandmahjong.com/', '2026-11-13', 'ACTIVE')
