-- Burlington: synagogue game and teacher plus four sessions
UPDATE "City" SET "published" = 1, "intro" = 'Burlington has a synagogue drop-in game and a beginner class. Ohavi Zedek Synagogue hosts weekly drop-in Mah Jongg on Wednesday mornings and evenings, with an RSVP for the evening session, and Lynda Siegel teaches its five-week beginner class, where students learn the basics of American Mah Jongg. Class dates are posted on the synagogue''s page, so check before you go. If you are new, the beginner class is the place to start.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'burlington';
